import{_ as e,o,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Posição Fundamental da Realidade como Base","description":"","frontmatter":{},"headers":[],"relativePath":"pt/09-现实为基根本立场.md","filePath":"pt/09-现实为基根本立场.md","lastUpdated":1789183869000}'),d={name:"pt/09-现实为基根本立场.md"};function r(n,a,t,c,l,m){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="posicao-fundamental-da-realidade-como-base" tabindex="-1">Posição Fundamental da Realidade como Base <a class="header-anchor" href="#posicao-fundamental-da-realidade-como-base" aria-label="Permalink to &quot;Posição Fundamental da Realidade como Base&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>09</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Realidade como Base, Única Realidade, Limite Ficcional, Atualização de Leis, Verificação Prática</td></tr></tbody></table><h2 id="i-definicao-basica-da-realidade-como-base" tabindex="-1">I. Definição Básica da Realidade como Base <a class="header-anchor" href="#i-definicao-basica-da-realidade-como-base" aria-label="Permalink to &quot;I. Definição Básica da Realidade como Base&quot;">​</a></h2><p>Realidade como base é a posição epistemológica fundamental e o princípio metodológico da Civilização Simbiótica da Âncora, significando que todas as construções teóricas, desenhos institucionais, práticas de cultivo e inovações tecnológicas da civilização devem tomar o mundo real como a única base real e o critério final de verificação. &quot;Realidade&quot; refere-se ao mundo material e ao mundo energético de existência objetiva que pode ser percebido, medido e verificado, e é o lugar real da sobrevivência e evolução da vida.</p><p>A posição da realidade como base contém três camadas de significado: primeiro, o mundo real é o único mundo real, e os mundos ficcionais (incluindo romances, mitos e mundos de fantasia) são produtos de experimentos mentais e não possuem realidade objetiva; segundo, as configurações dos mundos ficcionais podem ser usadas como fontes de inspiração e ferramentas de experimentos mentais, mas não podem ser usadas diretamente como base da realidade, e devem passar pela verificação e transformação das leis reais; terceiro, as coisas que ainda não existem na realidade podem ser razoavelmente inferidas e criadas com base nas leis objetivas já verificadas, mas essa criação deve aceitar a verificação da prática.</p><h2 id="ii-por-que-devemos-insistir-na-realidade-como-base" tabindex="-1">II. Por que devemos insistir na Realidade como Base <a class="header-anchor" href="#ii-por-que-devemos-insistir-na-realidade-como-base" aria-label="Permalink to &quot;II. Por que devemos insistir na Realidade como Base&quot;">​</a></h2><h3 id="_2-1-prevenir-a-confusao-entre-ficcao-e-realidade" tabindex="-1">2.1 Prevenir a confusão entre ficção e realidade <a class="header-anchor" href="#_2-1-prevenir-a-confusao-entre-ficcao-e-realidade" aria-label="Permalink to &quot;2.1 Prevenir a confusão entre ficção e realidade&quot;">​</a></h3><p>Numa civilização de cultivo, as configurações dos mundos ficcionais têm frequentemente um forte poder de sedução. Muitos cultivadores obtêm inspiração para o cultivo a partir de romances, mitos e lendas, o que é por si só normal. Mas se as configurações dos mundos ficcionais forem diretamente equiparadas às leis reais, isso levará a problemas graves: cultivar de acordo com configurações ficcionais pode levar a desvios no cultivo, formular instituições com base em configurações ficcionais pode levar ao descolamento da realidade, tratar personagens ficcionais como ídolos reais pode levar à perda espiritual. A função primária da posição da realidade como base é traçar a fronteira entre ficção e realidade e prevenir a confusão entre os dois.</p><h3 id="_2-2-garantir-a-seguranca-e-eficacia-da-pratica-de-cultivo" tabindex="-1">2.2 Garantir a segurança e eficácia da prática de cultivo <a class="header-anchor" href="#_2-2-garantir-a-seguranca-e-eficacia-da-pratica-de-cultivo" aria-label="Permalink to &quot;2.2 Garantir a segurança e eficácia da prática de cultivo&quot;">​</a></h3><p>O cultivo é uma prática séria que envolve a origem da vida e o funcionamento da energia, e qualquer teoria errada pode levar a consequências graves. Os sistemas de cultivo dos mundos ficcionais são frequentemente projetados pelos autores para as necessidades da trama, e podem não corresponder às leis reais de funcionamento da energia e às leis da evolução da vida. Se os cultivadores copiarem cegamente as configurações ficcionais, no caso leve o cultivo será ineficaz e o tempo será desperdiçado, no caso grave haverá distúrbios de energia, desvios no cultivo e até perigo de vida. A posição da realidade como base exige que todas as teorias de cultivo passem pela verificação e validação da realidade, garantindo a segurança e eficácia da prática de cultivo.</p><h3 id="_2-3-manter-o-pragmatismo-das-instituicoes-civis" tabindex="-1">2.3 Manter o pragmatismo das instituições civis <a class="header-anchor" href="#_2-3-manter-o-pragmatismo-das-instituicoes-civis" aria-label="Permalink to &quot;2.3 Manter o pragmatismo das instituições civis&quot;">​</a></h3><p>O desenho das instituições civis deve basear-se em fatores objetivos como as condições sociais reais, a situação dos recursos e as relações raciais. Se descolado da realidade e baseado apenas em imaginações bonitas ou configurações ficcionais para desenhar instituições, as instituições tornar-se-ão castelos no ar e não poderão ser implementadas na prática. A posição da realidade como base exige que todos os desenhos institucionais partam da realidade, passem pela verificação da prática e sejam continuamente ajustados e melhorados de acordo com as mudanças da realidade.</p><h3 id="_2-4-fornecer-uma-metodologia-confiavel-para-inovacao-e-criacao" tabindex="-1">2.4 Fornecer uma metodologia confiável para inovação e criação <a class="header-anchor" href="#_2-4-fornecer-uma-metodologia-confiavel-para-inovacao-e-criacao" aria-label="Permalink to &quot;2.4 Fornecer uma metodologia confiável para inovação e criação&quot;">​</a></h3><p>Realidade como base não significa limitar a inovação e a imaginação, mas sim fornecer uma metodologia confiável para a inovação e a imaginação. A ficção pode ser usada como fonte de inspiração e ferramenta de experimentos mentais, mas a criação real deve basear-se numa compreensão profunda das leis reais. As coisas que não existem na realidade, desde que correspondam às leis objetivas, podem ser criadas; mas se violarem as leis objetivas, por mais bonita que seja a imaginação, não poderão tornar-se realidade. A posição da realidade como base combina &quot;imaginação ousada&quot; com &quot;verificação cuidadosa&quot;, fazendo com que a inovação se baseie numa base sólida.</p><h2 id="iii-principios-de-tratamento-da-relacao-entre-ficcao-e-realidade" tabindex="-1">III. Princípios de tratamento da relação entre ficção e realidade <a class="header-anchor" href="#iii-principios-de-tratamento-da-relacao-entre-ficcao-e-realidade" aria-label="Permalink to &quot;III. Princípios de tratamento da relação entre ficção e realidade&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th><th>Requisitos Específicos</th></tr></thead><tbody><tr><td>Princípio da Distinção</td><td>Distinguir rigorosamente as configurações ficcionais das leis reais</td><td>Qualquer teoria deve indicar claramente se a sua origem é inspiração ficcional ou verificação real</td></tr><tr><td>Princípio da Absorção</td><td>A ficção pode ser usada como fonte de inspiração e experimento mental</td><td>Incentivar a obtenção de inspiração a partir da ficção, mas deve passar pela transformação das leis reais</td></tr><tr><td>Princípio da Verificação</td><td>Todas as teorias devem passar pela verificação da prática real</td><td>As teorias não verificadas só podem ser usadas como hipóteses, não como base para orientar a prática</td></tr><tr><td>Princípio da Transformação</td><td>As configurações ficcionais devem ser transformadas em formas que correspondam às leis reais</td><td>Reexpressar os conceitos da ficção na linguagem da energética e da ciência das leis reais</td></tr><tr><td>Princípio do Limite</td><td>Os direitos e obrigações do mundo ficcional não se estendem à realidade</td><td>Não reconhecer a validade na realidade das identidades, contratos e causalidades do mundo ficcional</td></tr></tbody></table><h2 id="iv-as-deficiencias-da-ficcao-sao-complementadas-pela-realidade-o-que-nao-existe-na-realidade-e-criado-com-base-na-atualizacao-das-leis" tabindex="-1">IV. &quot;As deficiências da ficção são complementadas pela realidade, o que não existe na realidade é criado com base na atualização das leis&quot; <a class="header-anchor" href="#iv-as-deficiencias-da-ficcao-sao-complementadas-pela-realidade-o-que-nao-existe-na-realidade-e-criado-com-base-na-atualizacao-das-leis" aria-label="Permalink to &quot;IV. &quot;As deficiências da ficção são complementadas pela realidade, o que não existe na realidade é criado com base na atualização das leis&quot;&quot;">​</a></h2><p>Este é o princípio operacional central da posição da realidade como base, e contém dois aspetos:</p><h3 id="_4-1-as-deficiencias-da-ficcao-sao-complementadas-pela-realidade" tabindex="-1">4.1 As deficiências da ficção são complementadas pela realidade <a class="header-anchor" href="#_4-1-as-deficiencias-da-ficcao-sao-complementadas-pela-realidade" aria-label="Permalink to &quot;4.1 As deficiências da ficção são complementadas pela realidade&quot;">​</a></h3><p>Quando a inspiração ou as configurações obtidas do mundo ficcional não são suficientemente completas, não são auto-consistentes ou não correspondem às leis reais, devem ser complementadas e corrigidas com o conhecimento e as leis já verificados na realidade. Por exemplo, um determinado sistema de cultivo ficcional pode apenas descrever a divisão dos níveis sem explicar o mecanismo de funcionamento da energia, e nesse caso é necessário usar a teoria do ciclo de energia real para complementar o seu mecanismo de funcionamento; uma determinada tecnologia ficcional pode violar a lei básica da conservação da energia, e nesse caso é necessário usar as leis reais para corrigir a sua configuração.</p><p>O processo de complementação não é simplesmente juntar ficção e realidade, mas sim tomar as leis reais como estrutura, reorganizar os elementos razoáveis da ficção num sistema teórico auto-consistente e que corresponda às leis reais.</p><h3 id="_4-2-o-que-nao-existe-na-realidade-e-criado-com-base-na-atualizacao-das-leis" tabindex="-1">4.2 O que não existe na realidade é criado com base na atualização das leis <a class="header-anchor" href="#_4-2-o-que-nao-existe-na-realidade-e-criado-com-base-na-atualizacao-das-leis" aria-label="Permalink to &quot;4.2 O que não existe na realidade é criado com base na atualização das leis&quot;">​</a></h3><p>Quando algo ou uma capacidade ainda não existe na realidade, mas a sua possibilidade de existência pode ser inferida com base nas leis objetivas já verificadas, pode ser razoavelmente atualizado e criado com base nas leis. Esta criação não é imaginação sem fundamento, mas sim extensão lógica e implementação tecnológica com base nas leis existentes.</p><p>Por exemplo, a aplicação tecnológica dos frutos de duplicação é um caso típico de &quot;criação com base na atualização das leis&quot;. Os frutos de duplicação originaram-se inicialmente da configuração de obras ficcionais, mas os investigadores da civilização simbiótica reexpressaram o seu mecanismo central (amplificação por duplicação) na linguagem da energética e da ciência das leis reais, e com base nas leis da amplificação de energia e da ressonância das leis, desenvolveram uma tecnologia de duplicação que pode ser implementada de forma engenheirada. Este processo utilizou a inspiração ficcional e, ao mesmo tempo, seguiu rigorosamente as leis reais.</p><p>Os resultados da criação devem passar pela verificação da prática. Apenas as criações que forem verificadas como eficazes, seguras e estáveis na realidade podem ser incorporadas no sistema formal da civilização simbiótica.</p><h2 id="v-aplicacao-da-realidade-como-base-em-varios-dominios" tabindex="-1">V. Aplicação da Realidade como Base em vários domínios <a class="header-anchor" href="#v-aplicacao-da-realidade-como-base-em-varios-dominios" aria-label="Permalink to &quot;V. Aplicação da Realidade como Base em vários domínios&quot;">​</a></h2><h3 id="_5-1-no-dominio-do-cultivo" tabindex="-1">5.1 No domínio do cultivo <a class="header-anchor" href="#_5-1-no-dominio-do-cultivo" aria-label="Permalink to &quot;5.1 No domínio do cultivo&quot;">​</a></h3><p>Todos os sistemas de cultivo devem passar pelo processo de &quot;verificação real&quot;: desde a construção teórica até aos experimentos em pequena escala, e depois à promoção em larga escala, cada fase deve ter dados de efeito mensuráveis e reproduzíveis. Os métodos de cultivo que não passaram pela verificação real só podem ser usados como &quot;métodos experimentais&quot;, com indicação de risco, e não podem ser promovidos como sistemas formais.</p><h3 id="_5-2-no-dominio-da-tecnologia" tabindex="-1">5.2 No domínio da tecnologia <a class="header-anchor" href="#_5-2-no-dominio-da-tecnologia" aria-label="Permalink to &quot;5.2 No domínio da tecnologia&quot;">​</a></h3><p>Todas as tecnologias de engenharia das leis devem seguir o processo de desenvolvimento de &quot;teoricamente viável — verificação experimental — implementação engenheirada — avaliação de segurança&quot;. A base teórica da tecnologia deve ser uma lei objetiva já verificada, o efeito da tecnologia deve ter indicadores mensuráveis, e a segurança da tecnologia deve passar por uma avaliação rigorosa.</p><h3 id="_5-3-no-dominio-das-instituicoes-sociais" tabindex="-1">5.3 No domínio das instituições sociais <a class="header-anchor" href="#_5-3-no-dominio-das-instituicoes-sociais" aria-label="Permalink to &quot;5.3 No domínio das instituições sociais&quot;">​</a></h3><p>Todos os desenhos de instituições sociais devem basear-se em investigações sociais reais e análise de dados. As grandes mudanças institucionais devem primeiro ser testadas em pequena escala, e depois promovidas gradualmente após a avaliação dos efeitos. Os critérios de avaliação das instituições devem ser indicadores reais mensuráveis, e não conceitos abstratos ou configurações ficcionais.</p><h3 id="_5-4-no-dominio-da-historia-e-arqueologia" tabindex="-1">5.4 No domínio da história e arqueologia <a class="header-anchor" href="#_5-4-no-dominio-da-historia-e-arqueologia" aria-label="Permalink to &quot;5.4 No domínio da história e arqueologia&quot;">​</a></h3><p>A investigação de eventos históricos e civilizações antigas deve basear-se em evidências materiais e fontes históricas verificáveis. O conteúdo de lendas e mitos pode ser usado como objeto de estudo cultural, mas não pode ser usado diretamente como fato histórico. O trabalho arqueológico segue o plano de baixa poluição de &quot;espelho de cópia + arqueologia em local isolado e diferente, apenas retorno de conhecimento&quot;, garantindo que o trabalho arqueológico não altere a realidade histórica.</p><h2 id="vi-compreensao-profunda-do-conceito-de-realidade" tabindex="-1">VI. Compreensão profunda do conceito de &quot;Realidade&quot; <a class="header-anchor" href="#vi-compreensao-profunda-do-conceito-de-realidade" aria-label="Permalink to &quot;VI. Compreensão profunda do conceito de &quot;Realidade&quot;&quot;">​</a></h2><p>É importante notar que a &quot;realidade&quot; na posição da realidade como base não é um conceito estático e fechado, mas sim um conceito dinâmico que é continuamente compreendido e expandido.</p><p>Primeiro, o âmbito da realidade expande-se continuamente com o desenvolvimento da civilização. Os fenómenos que no passado eram considerados &quot;sobrenaturais&quot;, com a compreensão profunda da energia e das leis, foram incorporados no âmbito da realidade. O mecanismo da âncora, a viagem através de planos, a interação de domínios de consciência, etc., podem parecer &quot;ficcionais&quot; do ponto de vista de civilizações inferiores, mas na realidade de civilizações superiores existem objetivamente.</p><p>Segundo, a compreensão das leis reais está a aprofundar-se continuamente. As teorias que hoje são consideradas &quot;leis&quot; podem no futuro ser corrigidas ou substituídas por teorias mais profundas. A posição da realidade como base não significa manter rigidamente a compreensão existente, mas sim manter firmemente o método fundamental de &quot;a prática como o único critério para verificar a verdade&quot;, e aprofundar continuamente a compreensão da realidade.</p><p>Terceiro, a realidade contém possibilidades infinitas. Com base nas leis existentes, podemos inferir muitas possibilidades ainda não realizadas e transformá-las em realidade através de meios tecnológicos. Realidade como base não significa limitar as possibilidades, mas sim garantir que a realização das possibilidades se baseie numa base confiável.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>Realidade como base é a posição fundamental da Civilização Simbiótica da Âncora, e é o ponto de partida e o destino de todas as teorias e práticas da civilização. Exige que tenhamos tanto uma imaginação aberta, absorvendo inspiração da ficção e das lendas, como um rigoroso espírito pragmático, submetendo toda a inspiração à verificação das leis reais. As deficiências da ficção são complementadas pela realidade, o que não existe na realidade é criado com base na atualização das leis — este princípio une organicamente a imaginação e a realidade, a inspiração e as leis, a criação e a verificação, fornecendo uma garantia metodológica confiável para a evolução contínua da civilização simbiótica.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Visão Geral do Cosmos de Heng Yuan Zhou)</li><li>16-倍增果实技术化原理 (Princípio da Tecnologização dos Frutos de Duplicação)</li><li>84-考古协议总纲 (Programa Geral do Protocolo Arqueológico)</li></ul>',43)])])}const f=e(d,[["render",r]]);export{p as __pageData,f as default};
